#!/usr/bin/env python3
# usage: prompts.py N   -> prints the full Seedance prompt for shot N (English), built from the fixed bible + rules.
# usage: prompts.py md  -> writes all prompts as Markdown (for the repo).
import sys
BIBLE = """CHARACTER REFERENCE (identity, clothes, ages and relative heights - the family already appears in the first frame and must keep looking exactly like that):
- Grandma (Teta Khadija): elderly woman, completely plain matte black abaya with NO embroidery or pattern and black hijab, NO glasses, NO necklace, NO pendant, NO earrings, NO jewelry at all (plain black abaya), the tallest. She is always on her feet: she never sits, kneels or squats; to reach low she only leans forward at the waist with straight legs.
- Zoozoo: the eldest girl (about 10), white hijab, long cream lace coat with ruffled collar, wide white trousers, cream shoes, small gold necklace; the tallest girl (up to Grandma's shoulder). She never kneels or squats.
- Noonoo: girl about 8, very long softly wavy JET-BLACK hair worn loose with a middle parting, reaching her waist (it never gets shorter or browner), loose pink T-shirt with a big lilac butterfly, small gold coin necklace, black cargo trousers, white sneakers; almost as tall as Zoozoo.
- Nadyah: girl about 6, very dark almost black hair combed straight back with no fringe, tied in exactly ONE ponytail at the back of her head (never two pigtails), solid royal-blue sleeveless vest with pockets (smooth cotton, NOT denim, no frayed edges) over a white top, royal-blue shorts, white sneakers, small gold heart necklace; a head shorter than Noonoo.
- Hoor: toddler about 2, very curly tight voluminous dark-brown curls gathered into two round puffy curly buns on top, each with a small CREAM bow, pink vest, white top, pink shorts, black shoes, small gold necklace; the smallest.
- Mishoo: chubby round short-haired grey TABBY cat with clear dark-grey stripes on back, head and tail, white chest, belly, muzzle and paws, gold collar with a small round bell; a cat who talks ONLY when this shot gives him a line (small, funny, slightly grumpy voice, mouth moves like a cartoon cat); otherwise he makes only cat sounds."""
RULES = """RULES: one continuous shot, no cuts, no scene change. Continue exactly from the first frame: same people, same positions, same sizes, same clothes and hair; nobody changes identity, no extra or duplicate characters, nobody appears from nowhere or vanishes (characters only enter or leave by walking in or out of frame). The modern cream-stone house with a FLAT roof (no roof tiles; glass balconies, wood slat screens, single dark-brown front door, mosaic column), the garden, the low wooden bench and props stay exactly as in the first frame and never morph. Nobody walks through the bench. Nothing green grows in the clay pots (plain brown soil). Bright sunny daytime: every lamp, ceiling downlight, wall light and interior light is OFF."""
LOCK = "CAMERA: on a tripod, no zoom, no pan, no tilt; the framing stays identical to the first frame for the whole shot."
def P(cam, action, speaker, line):
    talk = (f'DIALOGUE: only {speaker} speaks, once: "{line}" Nobody else says any words (laughs or gasps without words are fine).'
            if line else "DIALOGUE: no words at all (only giggles, footsteps, birdsong and cat sounds if described).")
    return "3D animated kids cartoon in the exact style of the first frame.\n" + (cam or LOCK) + "\nACTION: " + action + "\n" + talk + "\n" + RULES + "\n" + BIBLE
